<template>
  <main class="league-view">
    <AtlasPageHeader :eyebrow="t('competitions.league.marketsEyebrow')" :title="t('competitions.league.marketsHeroTitle')" :description="t('competitions.league.marketsHeroDescription')">
      <template #actions><div class="platforms" :aria-label="t('markets.platforms')"><a href="https://kalshi.com" target="_blank" rel="noopener">Kalshi <ExternalLink :size="13" /></a><a href="https://polymarket.com" target="_blank" rel="noopener">Polymarket <ExternalLink :size="13" /></a></div></template>
    </AtlasPageHeader>
    <p class="platform-note"><Info :size="16" />{{ t('markets.platformNote') }}</p>
    <section v-if="loading" class="markets-skeleton" aria-busy="true">
      <article class="result-card market-skeleton-card" aria-hidden="true"><span class="skeleton-heading" /><span class="skeleton-label" /><span class="skeleton-select" /><div class="skeleton-filter-row"><span v-for="filter in 4" :key="filter" /></div><div class="skeleton-market-grid"><span v-for="card in 4" :key="card" /></div></article>
      <article class="result-card market-skeleton-card" aria-hidden="true"><span class="skeleton-heading" /><div class="skeleton-futures-table"><span v-for="row in 6" :key="row" /></div><span class="skeleton-label" /><span class="skeleton-select" /></article>
    </section>
    <section v-else-if="error" class="state-panel state-error" role="alert"><p>{{ error }}</p><button type="button" @click="loadMarkets">{{ t('competitions.league.retry') }}</button></section>
    <template v-else>
      <nav class="mode-tabs" role="tablist" :aria-label="t('markets.modes.label')"><button id="league-match-tab" type="button" role="tab" :aria-selected="marketMode === 'match'" aria-controls="league-match-panel" @click="marketMode = 'match'">{{ t('markets.modes.match') }}</button><button id="league-season-tab" type="button" role="tab" :aria-selected="marketMode === 'season'" aria-controls="league-season-panel" @click="marketMode = 'season'">{{ t('markets.modes.tournament') }}</button></nav>
      <section id="league-match-panel" class="result-card market-form" role="tabpanel" aria-labelledby="league-match-tab" v-show="marketMode === 'match'" :aria-hidden="marketMode !== 'match'"><div class="selectors league-fixture-selector"><label for="market-fixture">{{ t('competitions.league.upcomingFixture') }}<select id="market-fixture" v-model="selectedFixtureId" @change="selectFixture"><option value="">{{ t('competitions.league.selectUpcoming') }}</option><option v-for="fixture in upcomingFixtures" :key="fixture.id" :value="fixture.id">{{ fixture.homeTeam.name }} {{ t('competitions.league.versus') }} {{ fixture.awayTeam.name }} · {{ format(fixture.kickoff) }}</option></select></label></div><div v-if="!fixtureQuestions.length && !fixtureError" class="form-footer"><p class="market-helper">{{ t('competitions.league.selectFixtureToGenerate') }}</p><button v-if="selectedFixtureId" type="button" :disabled="fixtureLoading" @click="loadFixtureMarkets">{{ fixtureLoading ? t('markets.form.matchLoading') : t('markets.form.matchAction') }}</button></div><nav v-if="selectedFixtureId && fixtureQuestions.length" class="filters" :aria-label="t('markets.filters.label')"><button v-for="filter in filters" :key="filter.key" type="button" :aria-pressed="activeFilter === filter.key" @click="activeFilter = filter.key">{{ filter.label }}</button></nav><p v-if="fixtureError" class="state-error">{{ fixtureError }}</p><section v-else-if="selectedQuestions.length" class="question-grid"><MarketCard v-for="question in selectedQuestions" :key="question.question_id" :question="question" :show-operator-details="false" /></section></section>
      <section id="league-season-panel" class="result-card" role="tabpanel" aria-labelledby="league-season-tab" v-show="marketMode === 'season'" :aria-hidden="marketMode !== 'season'"><section v-if="!seasonMarkets.length" class="tournament-run"><div><h2>{{ t('competitions.league.seasonFutures') }}</h2><p>{{ t('competitions.league.seasonFuturesDescription') }}</p></div><button type="button" :disabled="seasonLoading" @click="loadSeasonMarkets">{{ seasonLoading ? t('competitions.league.seasonLoading') : t('competitions.league.seasonAction') }}</button></section><template v-if="seasonMarkets.length"><header><h2>{{ t('competitions.league.seasonFutures') }}</h2><span>{{ t('competitions.league.modelImplied') }}</span></header><table><thead><tr><th scope="col">{{ t('competitions.league.club') }}</th><th scope="col">{{ t('competitions.league.champion') }}</th><th scope="col">{{ t('competitions.league.topFour') }}</th><th scope="col">{{ t('competitions.league.relegation') }}</th></tr></thead><tbody><tr v-for="row in seasonMarkets" :key="row.team.id"><th scope="row">{{ row.team.name }}</th><td>{{ percent(row.championProbability) }}</td><td>{{ percent(row.topFourProbability) }}</td><td>{{ percent(row.relegationProbability) }}</td></tr></tbody></table><label for="season-team">{{ t('competitions.league.selectClub') }}</label><select id="season-team" v-model="selectedSeasonTeamId"><option v-for="row in seasonMarkets" :key="row.team.id" :value="row.team.id">{{ row.team.name }}</option></select><section v-if="selectedSeasonQuestions.length" class="question-grid"><MarketCard v-for="question in selectedSeasonQuestions" :key="question.question_id" :question="question" :show-operator-details="false" /></section><p v-else>{{ t('competitions.league.noProjection') }}</p><p>{{ t('competitions.league.resolution') }}</p></template><p v-if="seasonError" class="state-error">{{ seasonError }}</p></section>
    </template>
  </main>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { useRoute } from 'vue-router'
import { api } from '../lib/api'
import { leagueApiBase } from '../competition/leagueApi.js'
import { ExternalLink, Info } from '@lucide/vue'
import MarketCard from '../components/MarketCard.vue'
import AtlasPageHeader from '../ui/patterns/AtlasPageHeader.vue'
const { locale, t } = useI18n(); const route = useRoute(); const loading = ref(true); const error = ref(''); const fixtureError = ref(''); const fixtureLoading = ref(false); const seasonError = ref(''); const seasonLoading = ref(false); const seasonMarkets = ref([]); const seasonQuestions = ref([]); const fixtureQuestions = ref([]); const upcomingFixtures = ref([]); const selectedFixtureId = ref(''); const selectedSeasonTeamId = ref(''); const activeFilter = ref('all'); const marketMode = ref('match')
const filters = computed(() => [{ key: 'all', label: t('competitions.league.all') }, { key: 'match_winner', label: t('markets.filters.matchWinner') }, { key: 'draw', label: t('markets.filters.draw') }, { key: 'btts', label: t('markets.filters.btts') }, { key: 'over_under', label: t('markets.filters.overUnder') }, { key: 'clean_sheet', label: t('markets.filters.cleanSheet') }, { key: 'correct_score', label: t('markets.filters.correctScore') }])
const selectedQuestions = computed(() => fixtureQuestions.value.filter((question) => question.tags?.includes(selectedFixtureId.value) && (activeFilter.value === 'all' || question.prop_type === activeFilter.value)))
const selectedSeasonQuestions = computed(() => seasonQuestions.value.filter((question) => question.tags?.includes(selectedSeasonTeamId.value)))
async function loadFixtureMarkets() { if (!selectedFixtureId.value) return; fixtureLoading.value = true; fixtureError.value = ''; try { const response = await api.post(`${leagueApiBase(route.params.competitionEditionSlug)}/markets/match`, { fixtureId: selectedFixtureId.value }); fixtureQuestions.value = response.data?.questions || [] } catch (cause) { fixtureError.value = cause.response?.data?.error || t('competitions.league.marketLoadFailed'); fixtureQuestions.value = [] } finally { fixtureLoading.value = false } }
function selectFixture() { fixtureQuestions.value = []; fixtureError.value = ''; activeFilter.value = 'all' }
async function loadSeasonMarkets() { seasonLoading.value = true; seasonError.value = ''; try { const response = await api.post(`${leagueApiBase(route.params.competitionEditionSlug)}/markets/season`); seasonMarkets.value = response.data?.seasonMarkets || []; seasonQuestions.value = response.data?.seasonQuestions || []; selectedSeasonTeamId.value = seasonMarkets.value[0]?.team?.id || '' } catch (cause) { seasonError.value = cause.response?.data?.error || t('competitions.league.marketLoadFailed') } finally { seasonLoading.value = false } }
async function loadMarkets() { loading.value = true; error.value = ''; try { const response = await api.get(`${leagueApiBase(route.params.competitionEditionSlug)}/markets`); const payload = response.data || {}; upcomingFixtures.value = (payload.fixtureMarkets || []).slice(0, 30).map((fixture) => ({ id: fixture.fixture, kickoff: fixture.kickoff, homeTeam: fixture.homeTeam, awayTeam: fixture.awayTeam })); selectedFixtureId.value = upcomingFixtures.value[0]?.id || '' } catch (cause) { error.value = cause.response?.data?.error || t('competitions.league.marketLoadFailed') } finally { loading.value = false } }
function format(value) { return new Intl.DateTimeFormat(locale.value, { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) }
function percent(value) { return new Intl.NumberFormat(locale.value, { style: 'percent', maximumFractionDigits: 1 }).format(Number(value) || 0) }
onMounted(loadMarkets)
</script>

