.form-footer button { border-radius: var(--radius-md); font-weight: var(--font-weight-bold); min-height: var(--control-height-lg); padding: 0 var(--space-5); }
@media (max-width: 640px) { .tournament-run { align-items: stretch; flex-direction: column; }.tournament-run button { width: 100%; } }
@media (max-width: 640px) { .form-footer { align-items: stretch; flex-direction: column; }.form-footer button { width: 100%; } }
.markets-skeleton { display: grid; gap: var(--space-6); }
