.skeleton-filter-row { border-bottom: var(--border-width-thin) solid var(--color-border); display: flex; gap: var(--space-2); padding-bottom: var(--space-3); }
.skeleton-filter-row span { height: 1.5rem; width: 4.5rem; }
.skeleton-market-grid { display: grid; gap: var(--space-3); grid-template-columns: repeat(2, minmax(0, 1fr)); }
